// ─── HELPERS ─────────────────────────────────────────────
const fmt$ = v => v>=1e6?`$${(v/1e6).toFixed(2)}M`:v>=1e3?`$${(v/1e3).toFixed(1)}K`:`$${Number(v).toLocaleString("es-EC",{minimumFractionDigits:2})}`;
const fmtN = v => Number(v).toLocaleString("es-EC");
const hoy  = () => new Date().toLocaleDateString("es-EC",{day:"2-digit",month:"short",year:"numeric"});
const uid  = () => Math.random().toString(36).slice(2,8).toUpperCase();
const dias = d => Math.floor((Date.now()-new Date(d))/86400000);

function useGuardar(k, ini) {
  const [v, setV] = useState(() => {
    try { const s = localStorage.getItem(k); return s ? JSON.parse(s) : ini; } catch { return ini; }
  });
  const set = useCallback(nv => {
    setV(nv);
    try { localStorage.setItem(k, JSON.stringify(nv)); } catch {}
  }, [k]);
  return [v, set];
}

// ─── COMPONENTES BASE ────────────────────────────────────
function KCard({icono, label, valor, sub, color, onClick}) {
  const col = color || C.verde;
  return (
    <div onClick={onClick} style={{background:C.card,border:`1px solid ${C.borde}`,borderRadius:12,padding:"16px 18px",borderTop:`3px solid ${col}`,cursor:onClick?"pointer":"default",transition:"background 0.15s"}}
      onMouseEnter={e=>{if(onClick)e.currentTarget.style.background=C.hover;}}
      onMouseLeave={e=>{e.currentTarget.style.background=C.card;}}>
      <div style={{fontSize:22,marginBottom:8}}>{icono}</div>
      <div style={{fontSize:24,fontWeight:800,color:C.texto,fontFamily:"monospace"}}>{valor}</div>
      <div style={{fontSize:11.5,fontWeight:600,color:C.texto,marginTop:3}}>{label}</div>
      {sub && <div style={{fontSize:10,color:C.gris,marginTop:2}}>{sub}</div>}
    </div>
  );
}

function Barra({label, valor, max, color, sufijo, pct}) {
  const col = color || C.verde;
  const w = pct != null ? pct : Math.min((valor/max)*100, 100);
  return (
    <div style={{marginBottom:10}}>
      <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
        <span style={{fontSize:11.5,color:C.texto}}>{label}</span>
        <span style={{fontSize:11.5,fontWeight:700,color:col,fontFamily:"monospace"}}>{typeof valor==="number"?valor.toLocaleString("es-EC"):valor}{sufijo||""}</span>
      </div>
      <div style={{height:7,background:C.panel,borderRadius:4,overflow:"hidden"}}>
        <div style={{height:"100%",width:`${w}%`,background:col,borderRadius:4}}/>
      </div>
    </div>
  );
}

function Semaforo({valor, meta, nombre, unidad, inv}) {
  const u = unidad || "";
  const ok   = inv ? valor <= meta : valor >= meta;
  const warn = inv ? valor <= meta * 1.15 : valor >= meta * 0.9;
  const col  = ok ? C.verde : warn ? C.amber : C.rojo;
  const bg   = ok ? C.verdeL : warn ? C.amberL : C.rojoL;
  return (
    <div style={{background:bg,borderRadius:10,padding:"12px 14px",borderLeft:`4px solid ${col}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
      <div>
        <div style={{fontSize:10,color:C.gris,textTransform:"uppercase",letterSpacing:0.5,marginBottom:2}}>{nombre}</div>
        <div style={{fontSize:20,fontWeight:800,color:col,fontFamily:"monospace"}}>{valor}{u}</div>
        <div style={{fontSize:10,color:C.gris}}>Meta: {meta}{u}</div>
      </div>
      <div style={{fontSize:26}}>{ok?"🟢":warn?"🟡":"🔴"}</div>
    </div>
  );
}

function SecCard({titulo, children, extra}) {
  return (
    <div style={{background:C.card,border:`1px solid ${C.borde}`,borderRadius:14,padding:"20px 22px"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
        <h3 style={{color:C.texto,fontSize:13,fontWeight:700,margin:0}}>{titulo}</h3>
        {extra}
      </div>
      {children}
    </div>
  );
}

function Titulo({area, titulo, sub, color}) {
  const col = color || C.verde;
  return (
    <div>
      <div style={{color:col,fontSize:11,letterSpacing:2,textTransform:"uppercase",marginBottom:4}}>{area}</div>
      <h1 style={{color:C.texto,fontSize:26,fontWeight:800,margin:0}}>{titulo}</h1>
      {sub && <p style={{color:C.gris,fontSize:13,margin:"4px 0 0"}}>{sub}</p>}
    </div>
  );
}

